@pytest.fixture()
def registry() -> FeedbackComparisonRegistry:
    root = Path(
        os.environ.get(
            "UPSTREAMDRIFT_REPO_ROOT", str(Path(__file__).resolve().parents[3])
        )
    )
    return FeedbackComparisonRegistry(EngineModelInventory.load(repo_root=root))


def _registry_binding(
    registry: FeedbackComparisonRegistry,
    bundle,
    engine: str,
) -> tuple[FeedbackComparisonRegistry, NativeAdapterBinding]:
    row = registry.get(f"{engine}/driver", "default", DriveMode.TORQUE)
    row = replace(
        row,
        source_model_sha256=bundle.model.source_model_sha256,
        provider_id="synthetic-inventory-provider",
        provider_sha256="e" * 64,
        availability="available",
    )
    registry.rows = tuple(
        row
        if (
            existing.package_id,
            existing.variant_id,
            existing.drive_mode,
        )
        == (row.package_id, row.variant_id, row.drive_mode)
        else existing
        for existing in registry.rows
    )
    return registry, NativeAdapterBinding(
        row.package_id,
        row.variant_id,
        row.drive_mode,
        bundle.model.model_id,
        bundle.model.variant_id,
        bundle.model.provider_id,
        bundle.model.provider_sha256,
        bundle.model.source_model_sha256,
        bundle.model.loaded_native_model_sha256,
        bundle.state_schema_sha256,
        bundle.input_channel_schema_sha256,
        bundle.model.ordered_input_channel_ids,
    )


def _rotate_wxyz(quaternion: np.ndarray, vector: np.ndarray) -> np.ndarray:
    scalar = quaternion[0]
    axis = quaternion[1:]
    cross = 2 * np.cross(axis, vector)
    return vector + scalar * cross + np.cross(axis, cross)


def _assert_calibration_replay_is_scored(
    registry: FeedbackComparisonRegistry,
    binding: NativeAdapterBinding,
    bundle,
    model_path: Path,
    poses: list[dict[str, tuple[np.ndarray, np.ndarray]]],
    engine_id: str,
) -> None:
    """Run a fresh native marker replay through the existing F09 scorer."""
    import hashlib

    from src.engines.feedback_comparison import (
        ComparisonEvidence,
        EvidenceMode,
        InputKind,
        ReplayPolicy,
    )
    from src.engines.feedback_marker_calibration import (
        NativeMarkerCalibrationRequest,
        calibrate_static_marker_attachments,
        capture_observation_sha256,
    )
    from src.engines.feedback_observation_qualification import (
        NativeObservationCase,
        build_feedback_observation_report,
        feedback_replay_identity_sha256,
    )
    from src.shared.python.motion_matching.acceptance import Horizon
    from src.shared.python.motion_matching.replay_metrics import (
        ObservedMarkerPositions,
        PositionInterpolation,
    )

    frame_id = "arm"
    offset = np.asarray([0.2, 0.1, -0.05])
    times = np.asarray(bundle.input_history.time_seconds, dtype=np.float64)
    capture_points = np.asarray(
        [pose[frame_id][0] @ offset + pose[frame_id][1] for pose in poses]
    )[:, None, :]
    capture = TourCapture(
        times,
        ("marker-a",),
        capture_points,
        np.ones((len(times), 1), dtype=bool),
        bundle.model.source_model_sha256,
    )
    pose_provider_id = f"{engine_id}-test-native-fullstate-fk"
    pose_provider_sha256 = hashlib.sha256(Path(__file__).read_bytes()).hexdigest()
    calibration_request = NativeMarkerCalibrationRequest(
        capture,
        {"marker-a": frame_id},
        poses,
        times,
        binding,
        engine_id,
        pose_provider_id,
        pose_provider_sha256,
        "world",
        "capture-relative",
    )
    calibration = calibrate_static_marker_attachments(calibration_request)
    calibration.validate(calibration_request)
    marker_map = calibration.to_native_marker_map(
        binding, output_timebase_id=bundle.input_history.timebase_id
    )
    fresh_marker_evidence = execute_native_marker_replay(
        NativeReplayRequest(binding, bundle, model_path), registry, marker_map
    )
    output = fresh_marker_evidence.native_output
    observations = ObservedMarkerPositions(
        time_s=output.time_s,
        positions_m=np.asarray(output.positions_m) + np.asarray([0.0, 0.0, 0.001]),
        valid=np.ones((len(times), 1), dtype=bool),
        marker_labels=output.marker_labels,
        frame_id=output.frame_id,
        timebase_id=output.timebase_id,
    )
    observation_capture = TourCapture(
        times,
        tuple(output.marker_labels),
        np.asarray(observations.positions_m),
        np.asarray(observations.valid, dtype=bool),
        bundle.model.source_model_sha256,
    )
    row = registry.get(binding.package_id, binding.variant_id, binding.drive_mode)
    position_dimension = sum(
        item.dimension
        for item in bundle.model.state_schema.components
        if item.role.value == "position"
    )
    velocity_dimension = sum(
        item.dimension
        for item in bundle.model.state_schema.components
        if item.role.value == "velocity"
    )
    comparison = ComparisonEvidence(
        package_id=row.package_id,
        variant_id=row.variant_id,
        drive_mode=row.drive_mode,
        source_model_sha256=row.source_model_sha256,
        provider_id=row.provider_id,
        provider_sha256=row.provider_sha256,
        state_schema_sha256=bundle.state_schema_sha256,
        policy_sha256=bundle.policy_sha256,
        applied_input_sha256=bundle.applied_input_sha256,
        input_kind=InputKind(bundle.input_history.input_kind.value),
        input_interpolation=bundle.input_history.interpolation.value,
        timebase_id=bundle.input_history.timebase_id,
        replay_policy=ReplayPolicy.INDEPENDENT_TIME_ONLY,
        evidence_mode=EvidenceMode(bundle.policy.replay_mode.value),
        horizon_s=float(times[-1]),
        observation_sha256=capture_observation_sha256(observation_capture),
        channel_ids=tuple(item.channel_id for item in bundle.input_history.channels),
        full_state=True,
        full_horizon=True,
        state_resets=0,
        nq=position_dimension,
        nv=velocity_dimension,
        physical_model_sha256=bundle.model.source_model_sha256,
        loaded_native_model_sha256=bundle.model.loaded_native_model_sha256,
        time_grid_sha256=bundle.time_grid_sha256,
        physics_sha256=bundle.model.loaded_native_model_sha256,
        contact_sha256=bundle.policy.contact_policy_sha256 or "",
        integrator_sha256=bundle.policy_sha256,
        input_channel_schema_sha256=bundle.input_channel_schema_sha256,
        initial_state_sha256=bundle.integrity.initial_state_sha256,
        comparison_contract_version="feedback-comparison/1.1.0",
    )
    case = NativeObservationCase(
        evidence=comparison,
        replay_bundle=bundle,
        source_replay_identity_sha256=feedback_replay_identity_sha256(
            comparison, bundle
        ),
        native_output=output,
        observations=observations,
        native_acceptance_receipt={"engine": engine_id, "capture": "driver"},
        horizon=Horizon.G3,
        interpolation=PositionInterpolation.LINEAR_POSITION,
        native_marker_evidence=fresh_marker_evidence,
    )

    report = build_feedback_observation_report(registry, (case,))

    scored = next(item for item in report.rows if item.package_id == row.package_id)
    assert scored.score is not None
    assert scored.score.native_marker_calibration_sha256 == calibration.sha256
    assert (
        scored.score.native_execution_receipt_sha256
        == fresh_marker_evidence.receipt_sha256
    )
    assert not report.is_qualified


def test_mujoco_markers_use_native_fk_with_floating_base_and_local_offset(
    registry: FeedbackComparisonRegistry,
    tmp_path: Path,
) -> None:
    mujoco = pytest.importorskip("mujoco")
    from src.engines.physics_engines.mujoco.python.native_torque_replay import (
        build_native_torque_bundle,
        replay_native_torque_bundle,
    )

    model_path = tmp_path / "floating_marker.xml"
    model_path.write_text(
        """<mujoco model="marker_fk">
  <option timestep="0.001" gravity="0 0 0"/>
  <worldbody><body name="root"><freejoint name="floating"/>
    <geom type="sphere" size="0.03" mass="1"/>
    <body name="arm" pos="0 0 0.3"><joint name="hinge" axis="0 0 1"/>
      <geom type="capsule" size="0.02 0.1" mass="1"/>
    </body>
  </body></worldbody>
  <actuator><motor name="motor" joint="hinge"/></actuator>
</mujoco>""",
        encoding="utf-8",
    )
    model = mujoco.MjModel.from_xml_path(str(model_path))
    data = mujoco.MjData(model)
    data.qpos[:7] = [0.2, -0.1, 0.4, math.sqrt(0.5), 0.0, 0.0, math.sqrt(0.5)]
    data.qpos[7] = 0.35
    mujoco.mj_forward(model, data)
    initial = np.empty(mujoco.mj_stateSize(model, mujoco.mjtState.mjSTATE_INTEGRATION))
    mujoco.mj_getState(model, data, initial, mujoco.mjtState.mjSTATE_INTEGRATION)
    bundle = build_native_torque_bundle(
        model_path,
        initial,
        np.asarray([0.0, 0.001, 0.002]),
        np.asarray([[0.1], [0.2], [0.2]]),
    )
    registry, binding = _registry_binding(registry, bundle, "mujoco")
    request = NativeReplayRequest(binding, bundle, model_path)
    offset = (0.2, -0.1, 0.05)
    replay = replay_native_torque_bundle(bundle, model_path)
    native_poses = []
    for qpos in replay.qpos:
        data.qpos[:] = qpos
        mujoco.mj_forward(model, data)
        native_poses.append(
            {
                "arm": (
                    np.asarray(data.xmat[model.body("arm").id]).reshape(3, 3).copy(),
                    np.asarray(data.xpos[model.body("arm").id]).copy(),
                )
            }
        )
    capture = TourCapture(
        np.asarray(bundle.input_history.time_seconds),
        ("marker-a",),
        np.asarray(
            [
                pose["arm"][0] @ np.asarray(offset) + pose["arm"][1]
                for pose in native_poses
            ]
        )[:, None, :],
        np.ones((len(native_poses), 1), dtype=bool),
        bundle.model.source_model_sha256,
    )
    pose_provider_id = "test-mujoco-mj-forward-fullstate-fk"
    pose_provider_sha256 = hashlib.sha256(Path(__file__).read_bytes()).hexdigest()
    calibration = calibrate_static_marker_attachments(
        NativeMarkerCalibrationRequest(
            capture,
            {"marker-a": "arm"},
            native_poses,
            capture.time_s,
            binding,
            "mujoco",
            pose_provider_id,
            pose_provider_sha256,
            "capture-world",
            "capture-relative",
        )
    )
    calibration.validate(
        NativeMarkerCalibrationRequest(
            capture,
            {"marker-a": "arm"},
            native_poses,
            capture.time_s,
            binding,
            "mujoco",
            pose_provider_id,
            pose_provider_sha256,
            "capture-world",
            "capture-relative",
        )
    )
    marker_map = calibration.to_native_marker_map(
        binding, output_timebase_id=bundle.input_history.timebase_id
    )
    with pytest.raises(ValueError, match="model or provider identity differs"):
        execute_native_marker_replay(
            request,
            registry,
            replace(marker_map, native_model_id="mujoco/driver"),
        )

    evidence = execute_native_marker_replay(request, registry, marker_map)

    positions = np.asarray(evidence.native_output.positions_m)
    assert positions.shape == (3, 1, 3)
    assert evidence.qualification == "unqualified"
    assert evidence.marker_map_sha256 == marker_map.sha256
    assert evidence.calibration_artifact_sha256 == calibration.sha256
    assert evidence.native_execution_receipt.output_state_sha256
    changed_map = replace(
        marker_map,
        attachments=(
            replace(marker_map.attachments[0], local_position_m=(0.21, -0.1, 0.05)),
        ),
    )
    assert changed_map.sha256 != marker_map.sha256
    for sample, state in enumerate(replay.qpos):
        angle = state[7]
        local = np.asarray(offset)
        hinge = np.array(
            [
                math.cos(angle) * local[0] - math.sin(angle) * local[1],
                math.sin(angle) * local[0] + math.cos(angle) * local[1],
                local[2],
            ]
        )
        local_from_root = np.array([0.0, 0.0, 0.3]) + hinge
        expected = state[:3] + _rotate_wxyz(state[3:7], local_from_root)
        np.testing.assert_allclose(positions[sample, 0], expected, atol=1e-10)


def test_marker_map_rejects_stale_loaded_model_identity(
    registry: FeedbackComparisonRegistry,
    tmp_path: Path,
) -> None:
    mujoco = pytest.importorskip("mujoco")
    from src.engines.physics_engines.mujoco.python.native_torque_replay import (
        build_native_torque_bundle,
    )

    model_path = tmp_path / "hinge.xml"
    model_path.write_text(
        """<mujoco model="marker_fk"><option timestep="0.001"/>
<worldbody><body name="arm">
 <joint name="hinge"/><geom type="capsule" size="0.02 0.1" mass="1"/>
</body></worldbody><actuator><motor name="motor" joint="hinge"/></actuator></mujoco>""",
        encoding="utf-8",
    )
    model = mujoco.MjModel.from_xml_path(str(model_path))
    data = mujoco.MjData(model)
    initial = np.empty(mujoco.mj_stateSize(model, mujoco.mjtState.mjSTATE_INTEGRATION))
    mujoco.mj_getState(model, data, initial, mujoco.mjtState.mjSTATE_INTEGRATION)
    bundle = build_native_torque_bundle(
        model_path,
        initial,
        np.asarray([0.0, 0.001, 0.002]),
        np.asarray([[0.1], [0.1], [0.1]]),
    )
    registry, binding = _registry_binding(registry, bundle, "mujoco")
    marker_map = NativeMarkerMap(
        "mujoco",
        bundle.model.model_id,
        bundle.model.variant_id,
        bundle.model.provider_id,
        bundle.model.provider_sha256,
        bundle.model.source_model_sha256,
        "f" * 64,
        "world",
        bundle.input_history.timebase_id,
        (NativeMarkerAttachment("marker-a", "arm", (0.0, 0.2, 0.0)),),
    )

    with pytest.raises(ValueError, match="model or provider identity differs"):
        execute_native_marker_replay(
            NativeReplayRequest(binding, bundle, model_path), registry, marker_map
        )

    valid_map = replace(
        marker_map, loaded_native_model_sha256=bundle.model.loaded_native_model_sha256
    )
    unknown_body = replace(
        valid_map,
        attachments=(replace(valid_map.attachments[0], frame_id="missing-body"),),
    )
    with pytest.raises(ValueError, match="unknown native marker body"):
        execute_native_marker_replay(
            NativeReplayRequest(binding, bundle, model_path), registry, unknown_body
        )


def test_marker_report_preserves_every_required_engine_without_fk_requests(
    registry: FeedbackComparisonRegistry,
) -> None:
    report = build_native_marker_replay_report(registry, ())

    assert len(report.rows) == len(registry.rows)
    assert set(report.required_engine_ids) == {
        "drake",
        "mujoco",
        "myosuite",
        "opensim",
        "pinocchio",
        "simscape",
    }
    assert report.missing_engine_ids == report.required_engine_ids
    assert not report.has_full_required_fk_coverage
    assert all(row.status == "missing_marker_map" for row in report.rows)


def test_drake_markers_use_native_fk_with_floating_base_and_local_offset(
    registry: FeedbackComparisonRegistry,
    tmp_path: Path,
) -> None:
    pytest.importorskip("pydrake.multibody.plant")
    from pydrake.math import RigidTransform
    from pydrake.multibody.parsing import Parser
    from pydrake.multibody.plant import MultibodyPlant

    from src.engines.physics_engines.drake.python.native_torque_replay import (
        build_native_drake_torque_bundle,
        replay_native_drake_torque_bundle,
    )

    urdf = """<robot name="floating_marker_fk">
  <link name="base"><inertial><mass value="2"/><inertia ixx="0.2" iyy="0.2" izz="0.2" ixy="0" ixz="0" iyz="0"/></inertial></link>
  <link name="arm"><inertial><mass value="1"/><inertia ixx="0.1" iyy="0.1" izz="0.1" ixy="0" ixz="0" iyz="0"/></inertial></link>
  <joint name="hinge" type="revolute"><parent link="base"/><child link="arm"/><axis xyz="0 0 1"/><limit lower="-3" upper="3" effort="2" velocity="100"/></joint>
  <transmission name="motor"><type>transmission_interface/SimpleTransmission</type><joint name="hinge"/><actuator name="motor"><mechanicalReduction>1</mechanicalReduction></actuator></transmission>
</robot>"""
    model_path = tmp_path / "floating_marker.urdf"
    model_path.write_text(urdf, encoding="utf-8")
    plant = MultibodyPlant(0.001)
    plant.SetUseSampledOutputPorts(False)
    Parser(plant).AddModelsFromString(urdf, "urdf")
    plant.Finalize()
    context = plant.CreateDefaultContext()
    plant.SetFreeBodyPose(
        context,
        plant.GetBodyByName("base"),
        RigidTransform(np.asarray([0.3, -0.2, 0.5])),
    )
    plant.GetJointByName("hinge").set_angle(context, 0.4)
    initial = context.get_discrete_state_vector().CopyToVector()
    bundle = build_native_drake_torque_bundle(
        model_path,
        initial,
        np.asarray([0.0, 0.001, 0.002]),
        np.zeros((3, 1)),
    )
    registry, binding = _registry_binding(registry, bundle, "drake")
    offset = np.asarray([0.2, 0.1, 0.05])
    marker_map = NativeMarkerMap(
        "drake",
        bundle.model.model_id,
        bundle.model.variant_id,
        bundle.model.provider_id,
        bundle.model.provider_sha256,
        bundle.model.source_model_sha256,
        bundle.model.loaded_native_model_sha256,
        "world",
        bundle.input_history.timebase_id,
        (NativeMarkerAttachment("marker-a", "arm", tuple(offset)),),
    )

    evidence = execute_native_marker_replay(
        NativeReplayRequest(binding, bundle, model_path), registry, marker_map
    )

    positions = np.asarray(evidence.native_output.positions_m)
    assert evidence.native_execution_receipt.nq == 8
    assert evidence.native_execution_receipt.nv == 7
    assert evidence.native_execution_receipt.state_reset_allowed is False
    assert evidence.native_execution_receipt.state_reset_count is None
    assert np.all(np.linalg.norm(positions[:, 0], axis=1) > 0)
    frame = plant.GetFrameByName("arm")
    replayed = replay_native_drake_torque_bundle(bundle, model_path)
    pose_history = []
    for sample, qpos in enumerate(replayed.qpos):
        plant.SetPositions(context, qpos)
        pose = frame.CalcPoseInWorld(context)
        pose_history.append(
            {
                "arm": (
                    np.asarray(pose.rotation().matrix()).copy(),
                    np.asarray(pose.translation()).copy(),
                )
            }
        )
        expected = pose.translation() + pose.rotation().matrix() @ offset
        np.testing.assert_allclose(positions[sample, 0], expected, atol=1e-10)
    _assert_calibration_replay_is_scored(
        registry, binding, bundle, model_path, pose_history, "drake"
    )


def test_pinocchio_markers_use_native_fk_with_floating_base_and_local_offset(
    registry: FeedbackComparisonRegistry,
    tmp_path: Path,
) -> None:
    pin = pytest.importorskip("pinocchio")
    version = getattr(pin, "__version__", None)
    if not isinstance(version, str):
        pytest.skip("real Pinocchio runtime is unavailable")
    assert version.startswith("4.1")
    from src.engines.physics_engines.pinocchio.python import native_torque_replay
    from src.engines.physics_engines.pinocchio.python.pinocchio_physics_engine import (
        PinocchioPhysicsEngine,
    )

    urdf = """<robot name="floating_marker_fk">
<link name="world"/>
<link name="base"><inertial><mass value="2"/><inertia ixx="0.2" iyy="0.2" izz="0.2" ixy="0" ixz="0" iyz="0"/></inertial></link>
<joint name="root" type="floating"><parent link="world"/><child link="base"/></joint>
<link name="arm"><inertial><mass value="1"/><inertia ixx="0.1" iyy="0.1" izz="0.1" ixy="0" ixz="0" iyz="0"/></inertial></link>
<joint name="hinge" type="revolute"><parent link="base"/><child link="arm"/><origin xyz="0.1 0 0.3"/><axis xyz="0 1 0"/><limit lower="-3" upper="3" effort="2" velocity="100"/></joint>
<transmission name="motor"><type>transmission_interface/SimpleTransmission</type><joint name="hinge"><hardwareInterface>EffortJointInterface</hardwareInterface></joint><actuator name="motor"><hardwareInterface>EffortJointInterface</hardwareInterface><mechanicalReduction>1</mechanicalReduction></actuator></transmission>
</robot>"""
    model_path = tmp_path / "floating_marker.urdf"
    model_path.write_text(urdf, encoding="utf-8")
    engine = PinocchioPhysicsEngine()
    engine.load_from_path(str(model_path))
    assert engine.model.nq == 8 and engine.model.nv == 7
    initial_q = pin.neutral(engine.model)
    initial_q[:3] = [0.3, -0.2, 0.5]
    initial_q[3:7] = [0.0, 0.0, math.sin(0.35), math.cos(0.35)]
    initial_q[7] = 0.4
    initial_v = np.zeros(engine.model.nv)
    initial_v[5] = 0.2
    bundle = native_torque_replay.build_native_pinocchio_torque_bundle(
        model_path,
        initial_q,
        initial_v,
        np.asarray([0.0, 0.001, 0.002]),
        np.zeros((3, 1)),
    )
    registry, binding = _registry_binding(registry, bundle, "pinocchio")
    request = NativeReplayRequest(binding, bundle, model_path)
    offset = (0.2, 0.1, -0.05)
    marker_map = NativeMarkerMap(
        "pinocchio",
        bundle.model.model_id,
        bundle.model.variant_id,
        bundle.model.provider_id,
        bundle.model.provider_sha256,
        bundle.model.source_model_sha256,
        bundle.model.loaded_native_model_sha256,
        "world",
        bundle.input_history.timebase_id,
        (NativeMarkerAttachment("marker-a", "arm", offset),),
    )
    with pytest.raises(ValueError, match="model or provider identity differs"):
        execute_native_marker_replay(
            request,
            registry,
            replace(marker_map, native_model_id="pinocchio/driver"),
        )

    evidence = execute_native_marker_replay(request, registry, marker_map)

    output = evidence.native_output
    positions = np.asarray(output.positions_m)
    assert positions.shape == (3, 1, 3)
    assert evidence.qualification == "unqualified"
    assert evidence.native_execution_receipt.nq == 8
    assert evidence.native_execution_receipt.nv == 7
    assert evidence.native_execution_receipt.package_id == "pinocchio/driver"
    assert evidence.native_execution_receipt.native_model_id == "native-model"
    report = build_native_marker_replay_report(
        registry, (NativeMarkerRequest(request, marker_map),)
    )
    assert len(report.rows) == len(registry.rows)
    pinocchio_row = next(
        row
        for row in report.rows
        if (row.package_id, row.variant_id) == ("pinocchio/driver", "default")
    )
    assert pinocchio_row.status == "marker_output_generated"
    execution_report = build_native_replay_report(registry, (request,))
    assert len(execution_report.rows) == len(registry.rows)
    assert execution_report.required_engine_ids == report.required_engine_ids
    assert execution_report.executed_row_count == 1
    assert not execution_report.is_complete
    assert report.missing_engine_ids == (
        "drake",
        "mujoco",
        "myosuite",
        "opensim",
        "simscape",
    )
    assert not report.has_full_required_fk_coverage
    replay = native_torque_replay.replay_native_pinocchio_torque_bundle(
        bundle, model_path
    )
    with pytest.raises(ValueError, match="unknown or ambiguous native marker frame"):
        native_torque_replay.native_marker_positions_from_replay(
            bundle,
            model_path,
            replay,
            (("marker-a", "unknown-frame", offset),),
        )
    pose_history = []
    frame_id = engine.model.getFrameId("arm")
    for sample, qpos in enumerate(replay.qpos):
        pin.forwardKinematics(engine.model, engine.data, qpos)
        pin.updateFramePlacements(engine.model, engine.data)
        frame_pose = engine.data.oMf[frame_id]
        pose_history.append(
            {
                "arm": (
                    np.asarray(frame_pose.rotation).copy(),
                    np.asarray(frame_pose.translation).copy(),
                )
            }
        )
        expected = frame_pose.translation + frame_pose.rotation @ np.asarray(offset)
        np.testing.assert_allclose(positions[sample, 0], expected, atol=1e-10)
    _assert_calibration_replay_is_scored(
        registry, binding, bundle, model_path, pose_history, "pinocchio"
    )
